    /// Whether this parsed command may trigger a pre-command automatic update.
    ///
    /// This operates on clap's canonical command variant so aliases such as
    /// `dr` inherit the same policy as `doctor`.
    fn allows_auto_update(&self) -> bool {
        !matches!(
            self,
            Self::Activate(_)
                | Self::Completion(_)
                | Self::Deactivate(_)
                | Self::Doctor(_)
                | Self::HookEnv(_)
                | Self::HookNotFound(_)
                | Self::Implode(_)
                | Self::SelfUpdate(_)
                | Self::Settings(_)
                | Self::Shell(_)
                | Self::Ssh(_)
                | Self::Usage(_)
                | Self::Version(_)
        )
    }

    /// Shell integration runs on startup and every prompt, so it must not do
    /// an all-project tracked-config scan or mutate installed tools. Deferred
    /// cleanup will run on the next ordinary command instead.
    fn allows_tool_purgatory_auto_prune(&self) -> bool {
        !matches!(
            self,
            Self::Activate(_)
                | Self::Deactivate(_)
                | Self::HookEnv(_)
                | Self::HookNotFound(_)
                | Self::Ssh(_)
        )
    }

    fn implicitly_trusts_active_config(&self) -> bool {
        matches!(
            self,
            Self::Exec(_) | Self::Install(_) | Self::Run(_) | Self::Watch(_)
        )
    }

    pub(crate) async fn run(self) -> Result<()> {
use std::io::{BufRead, Write};

/// Supply mise's GitHub token to Git's credential protocol.
#[derive(Debug, usage_rs::Args)]
#[usage(hide = true)]
pub(crate) struct GitCredential {
    operation: String,
}

impl GitCredential {
    pub(crate) fn run(self) -> eyre::Result<()> {
        if self.operation != "get" {
            return Ok(());
        }
        let mut protocol = String::new();
        let mut host = String::new();
        for line in std::io::stdin().lock().lines() {
            let line = line?;
            if line.is_empty() {
                break;
            }
            if let Some(value) = line.strip_prefix("protocol=") {
                protocol = value.to_owned();
            } else if let Some(value) = line.strip_prefix("host=") {
                host = value.to_owned();
            }
        }
        if protocol == "https"
            && host == "github.com"
            && let Some((token, _)) = crate::github::resolve_token_for_git(&host)
            && !token.contains(['\n', '\r', '\0'])
        {
